import{_ as a,C as s,c as r,o as i,a3 as e,G as o}from"./chunks/framework.Dokpd4od.js";const y=JSON.parse('{"title":"Locations","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/inventories/warehouses/locations.md","filePath":"master/supply-chain/inventories/warehouses/locations.md","lastUpdated":1791902625000}'),l={name:"master/supply-chain/inventories/warehouses/locations.md"};function c(d,t,p,h,g,u){const n=s("ImagePopup");return i(),r("div",null,[t[0]||(t[0]=e('<h1 id="locations" tabindex="-1">Locations <a class="header-anchor" href="#locations" aria-label="Permalink to &quot;Locations&quot;">​</a></h1><p>A location is a named place where stock can be: a shelf, a zone, a dock, or even a virtual place such as &quot;Customers&quot;. Locations sit inside each other, like folders. Every stock move goes from one location to another, so the tree you build here shapes all your documents.</p><blockquote><p><strong>In simple words:</strong> Locations are the shelves and zones of your warehouse. Each one has a type that tells the system what kind of place it is.</p></blockquote><p>Open <code>Inventory → Configurations → Warehouse Management → Locations</code>.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>The <strong>Locations</strong> menu appears only when <strong>Locations</strong> is on.</p><ol><li>Go to <code>Inventory → Settings → Manage Warehouses</code>.</li><li>Turn on <strong>Locations</strong> (&quot;Track product location in your warehouse&quot;).</li><li>Click <strong>Save changes</strong>.</li></ol><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The list shows the <strong>Location</strong> (full path), <strong>Type</strong>, <strong>Storage Category</strong> and <strong>Company</strong>. The list opens on the <strong>Internal</strong> tab. Tabs above it filter by type: <strong>All</strong> (18), <strong>Internal</strong> (9), <strong>Customer</strong> (1), <strong>Production</strong> (1), <strong>Vendor</strong> (1) and <strong>Archived</strong> (2). You can group by <strong>Warehouse</strong>, <strong>Type</strong>, <strong>Created At</strong> or <strong>Updated At</strong>.</p>',9)),o(n,{src:"/images1/inventory/loc_list.png",alt:"Locations list on the Internal tab, with tabs All, Internal, Customer, Production, Vendor and Archived"}),t[1]||(t[1]=e(`<h2 id="parent-and-child-locations" tabindex="-1">Parent and child locations <a class="header-anchor" href="#parent-and-child-locations" aria-label="Permalink to &quot;Parent and child locations&quot;">​</a></h2><p>A child sits inside a parent. The full name joins the names with a slash, so <strong>Stock</strong> inside <strong>WH</strong> is <strong>WH/Stock</strong>. The dev app has this tree (it also holds sample locations such as <strong>WH/Stock/Rack A1</strong> and <strong>WH/Stock/Shelf A</strong>):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Physical Locations</span></span>
<span class="line"><span>└── WH</span></span>
<span class="line"><span>    ├── Stock</span></span>
<span class="line"><span>    │   ├── Rack A1</span></span>
<span class="line"><span>    │   └── Shelf A</span></span>
<span class="line"><span>    ├── Input</span></span>
<span class="line"><span>    ├── Quality Control</span></span>
<span class="line"><span>    ├── Output</span></span>
<span class="line"><span>    ├── Packing Zone</span></span>
<span class="line"><span>    ├── Pre-Production</span></span>
<span class="line"><span>    └── Post-Production</span></span>
<span class="line"><span>Partners</span></span>
<span class="line"><span>├── Vendors</span></span>
<span class="line"><span>└── Customers</span></span>
<span class="line"><span>Virtual Locations</span></span>
<span class="line"><span>├── Inventory Adjustment</span></span>
<span class="line"><span>├── Production</span></span>
<span class="line"><span>└── Scrap</span></span></code></pre></div><p>Stock in a child counts toward its parent. A location of type <strong>View</strong> is only a folder and never holds stock itself.</p><h2 id="location-types" tabindex="-1">Location types <a class="header-anchor" href="#location-types" aria-label="Permalink to &quot;Location types&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>Meaning</th><th>Dev example</th></tr></thead><tbody><tr><td><strong>View</strong></td><td>A grouping folder. It holds no stock.</td><td>WH, Partners</td></tr><tr><td><strong>Internal Location</strong></td><td>A real place in your warehouse where stock lives.</td><td>WH/Stock</td></tr><tr><td><strong>Vendor Location</strong></td><td>Stands for your suppliers. Receipts start here.</td><td>Partners/Vendors</td></tr><tr><td><strong>Customer Location</strong></td><td>Stands for your customers. Deliveries end here.</td><td>Partners/Customers</td></tr><tr><td><strong>Transit Location</strong></td><td>Goods on the way between sites.</td><td>Inter Warehouse Transit (archived)</td></tr><tr><td><strong>Production</strong></td><td>Where materials are used up or made in manufacturing.</td><td>Virtual Locations/Production</td></tr><tr><td><strong>Inventory Loss</strong></td><td>Where lost, scrapped or corrected stock goes.</td><td>Virtual Locations/Scrap</td></tr></tbody></table><h2 id="create-a-location" tabindex="-1">Create a location <a class="header-anchor" href="#create-a-location" aria-label="Permalink to &quot;Create a location&quot;">​</a></h2><ol><li>Click <strong>New Location</strong>.</li><li>Fill the two cards, <strong>General</strong> and <strong>Settings</strong>.</li><li>Click <strong>Create</strong>.</li></ol>`,8)),o(n,{src:"/images1/inventory/loc_create_internal.png",alt:"Create Location form with Rack A1, parent WH/Stock, type Internal Location and cyclic counting frequency 30"}),t[2]||(t[2]=e('<h3 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h3><ul><li><strong><em>Location:</em></strong> The short name, for example <strong>Rack A1</strong>. Required.</li><li><strong><em>Parent Location:</em></strong> The place that contains it, such as <strong>WH/Stock</strong>. The full name becomes <strong>WH/Stock/Rack A1</strong>.</li><li><strong>External Notes:</strong> Free text about the place. It is a rich text box.</li></ul><h3 id="settings-1" tabindex="-1">Settings <a class="header-anchor" href="#settings-1" aria-label="Permalink to &quot;Settings&quot;">​</a></h3><ul><li><p><strong><em>Location Type:</em></strong> Required. The default is <strong>Internal Location</strong>.</p></li><li><p><strong><em>Company:</em></strong> Your current company.</p></li><li><p><strong><em>Storage Category:</em></strong> Limits what the place can hold. Click <strong>+</strong> next to it to create a category on the spot. See <a href="./storage-categories.html">Storage categories</a>. The card also has three toggles:</p></li><li><p><strong><em>Is a Scrap Location?</em></strong> Marks a place for scrapped or damaged goods.</p></li><li><p><strong><em>Is a Dock Location?</em></strong> Marks a place for goods ready to ship.</p></li><li><p><strong><em>Is a Replenish Location?</em></strong> Marks a place used to refill stock. <strong>WH/Stock</strong> has this on.</p></li></ul><p>The fields you see depend on the type.</p><table tabindex="0"><thead><tr><th>Type</th><th>Fields shown</th></tr></thead><tbody><tr><td>View, Vendor, Customer, Production</td><td><strong>Company</strong>, <strong>Is a Dock Location?</strong></td></tr><tr><td>Internal Location</td><td><strong>Storage Category</strong>, scrap, dock, replenish, cyclic counting</td></tr><tr><td>Inventory Loss</td><td>Scrap and dock toggles</td></tr><tr><td>Transit Location</td><td>Dock toggle and cyclic counting</td></tr></tbody></table><h3 id="cyclic-counting" tabindex="-1">Cyclic counting <a class="header-anchor" href="#cyclic-counting" aria-label="Permalink to &quot;Cyclic counting&quot;">​</a></h3><p>Cyclic counting lets you count one location on a regular schedule instead of once a year. It shows for Internal and Transit locations.</p><ul><li><strong><em>Inventory Frequency:</em></strong> The number of days between counts. 0 means no cyclic schedule.</li><li><strong>Last Inventory:</strong> The date of the last count. The system fills it.</li><li><strong>Next expected:</strong> The next planned count. The system works it out.</li></ul><p>See <a href="./../adjustments/inventory-adjustments.html">Inventory adjustments</a>.</p><h2 id="print-barcodes" tabindex="-1">Print barcodes <a class="header-anchor" href="#print-barcodes" aria-label="Permalink to &quot;Print barcodes&quot;">​</a></h2><ol><li>Tick one or more locations in the list.</li><li>Open the bulk actions menu.</li><li>Click <strong>Print Barcode</strong>.</li></ol><p>The bulk actions menu also has <strong>Restore selected</strong>, <strong>Delete selected</strong> and <strong>Force delete selected</strong>.</p><p>The edit page also has a <strong>Print</strong> button for one location. Barcodes help in <a href="./../barcode/scan-operations.html">Scan operations</a>.</p>',14)),o(n,{src:"/images1/inventory/loc_print_barcode.png",alt:"Locations list with WH/Stock and WH/Input ticked and the bulk Print Barcode action"}),t[3]||(t[3]=e('<h2 id="actions-and-statuses" tabindex="-1">Actions and statuses <a class="header-anchor" href="#actions-and-statuses" aria-label="Permalink to &quot;Actions and statuses&quot;">​</a></h2><ul><li><strong>Edit</strong> and <strong>View</strong> open the record.</li><li><strong>Delete</strong> archives it. A location still used by stock or documents cannot be deleted.</li><li>Archived locations appear under <strong>Archived</strong> and can be restored.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./warehouses.html">Warehouses</a></li><li><a href="./storage-categories.html">Storage categories</a></li><li><a href="./operation-types.html">Operation types</a></li><li><a href="./../routes/putaway-rules.html">Putaway rules</a></li></ul>',4))])}const b=a(l,[["render",c]]);export{y as __pageData,b as default};
